import type { Dispatch, ReactNode, SetStateAction } from 'react';

export type MenuBarContextProps = {
  /**
   * Currently opened Menu.Dropdown id,
   * which generated by `useId()`, so do not
   * set it manually, unless you want to close dropdown.
   */
  openId: string | null;
  /** Sets `openId` */
  setOpenId: Dispatch<SetStateAction<string | null>>;
};

export type MenuBarProps = {
  /** Items which will be inside. */
  children: ReactNode;
} & Partial<{
  /** Class name to pass into the component. */
  className: string;
  /** Whether the element is non-interactive. */
  disabled: boolean;
}>;

export type MenuDropdownProps = {
  /** Displayed dropdown text. */
  display: ReactNode;
} & Partial<{
  /** Width at which the dropdown will be opened. */
  openWidth: string | number;
}> &
  MenuBarProps;

export type MenuItemProps = Partial<{
  /** Adds check icon on left side if true. */
  checked: boolean;
  /** Action which will be performed on click. */
  onClick: (event: any) => void;
}> &
  MenuBarProps;
